MIN_ADV = 20000000.0
CONTEXT = ['spy_fo']              # lab context columns (config `context:`), point-in-time per 5-minute bar
CONDS = [
    ('day_vs_prev_range', '>=', 1.5),
    ('new_hod', '==', 1.0),
    ('slope6_atr', '>=', 0.03),
    ('spy_fo', '<', 0.0),
]
LAYERS = ['day_vs_prev_range >= 1.5', 'new_hod == 1', 'slope6_atr >= 0.03', 'spy_fo < 0', 'window 950-1100']


def mask(df) -> np.ndarray:
    x = compute(df, names=['day_vs_prev_range', 'new_hod', 'slope6_atr'], context=False)
    tod = df["tod"].to_numpy(dtype=float)
    m = (tod >= WINDOW[0]) & (tod <= WINDOW[1])
    with np.errstate(invalid="ignore"):
        for nm, op, v in CONDS:
            if nm in CONTEXT:
                a = df[nm].to_numpy(dtype=float) if nm in df.columns else np.full(len(df), np.nan)
            else:
                a = x[nm].to_numpy(dtype=np.float32).astype(float)
                v = float(np.float32(v))
            if op == "<=":
                m &= a <= v
            elif op == "<":
                m &= a < v
            elif op == ">=":
                m &= a >= v
            elif op == ">":
                m &= a > v
            else:
                m &= a == v
    return np.asarray(m, dtype=bool)
